const enriched = items.map(t => {
  const info = hotelLookup[t.suburb] || { hotel: "Wyndham Budget Partner", addr: t.suburb, rate: 55.0, rating: 4.0, reviews: 1000, dist: 0.35, safety: 90.0, crime: 15.0, walk: 80, cat: "Safe Corridor" };
  const baseCost = info.rate <= 50 ? (100 - (50 - info.rate)*0.5) : (100 - (info.rate - 50)*0.8);
  const costScore = Number(Math.min(100.0, Math.max(30.0, baseCost + (info.rating - 3.5)*5.0)).toFixed(1));
  const commuteScore = Number(Math.max(30.0, Math.min(100.0, 100.0 - (t.commute_minutes * 0.65) - ((t.transfers || 0)*8.0))).toFixed(1));
  const transitScore = Number(Math.max(35.0, Math.min(100.0, (info.walk * 0.70) + 30.0 - (info.dist * 15.0))).toFixed(1));
  const overall = Number(((0.35 * info.safety) + (0.30 * costScore) + (0.20 * commuteScore) + (0.15 * transitScore)).toFixed(2));

  return {
    city: t.city, downtown: t.downtown, suburb: t.suburb, transit_system: t.transit_system, transit_mode: t.transit_mode, nearest_station: t.nearest_station, commute_minutes: t.commute_minutes, transfers: t.transfers, fare_usd: t.fare_usd,
    hotel_name: info.hotel, address: info.addr, nightly_rate_usd: info.rate, rating: info.rating, review_count: info.reviews, distance_to_station_miles: info.dist,
    safety_score: info.safety, crime_index: info.crime, walkability: info.walk, category: info.cat,
    cost_score: costScore, commute_score: commuteScore, transit_score: transitScore, overall_score: overall
  };
});

const cities = [...new Set(enriched.map(e => e.city))];
const finalData = [];
cities.forEach(c => {
  const cityItems = enriched.filter(e => e.city === c);
  cityItems.sort((a, b) => b.overall_score - a.overall_score);
  cityItems.forEach((item, idx) => {
    item.rank = idx + 1;
    const badge = item.rank === 1 ? "⭐ #1 Recommended Location" : (item.rank === 2 ? "🥈 Prime Alternative" : (item.rank === 3 ? "🥉 Strong Value Option" : "✓ Viable Transit Option"));
    item.recommendation = `${badge} | ${item.suburb} provides a ${item.commute_minutes}-min commute to ${item.downtown} via ${item.transit_system} (${item.nearest_station}) at $${item.nightly_rate_usd.toFixed(0)}/night (Budget Match: $50-$60) with Safety Score of ${item.safety_score}/100 and Overall Score of ${item.overall_score}.`;
    finalData.push(item);
  });
});

return finalData.map(d => ({ json: d }));

// ==============================================================================
// STEP 9: DATA QUALITY & VALIDATION GATE
// ==============================================================================
const records = $input.all().map(i => i.json);
const errors = [];
const warnings = [];

records.forEach(r => {
  if (r.commute_minutes > 90) errors.push(`Commute > 90m: ${r.suburb}`);
  if (r.nightly_rate_usd <= 0 || r.nightly_rate_usd > 60) warnings.push(`Rate ${r.hotel_name}: $${r.nightly_rate_usd}`);
});

return [{
  json: {
    validation_status: errors.length === 0 ? "PASS" : "FAIL",
    total_records: records.length,
    budget_compliance: `${records.filter(r => r.nightly_rate_usd <= 60).length}/${records.length} properties <= $60`,
    errors: errors,
    warnings: warnings,
    execution_time: new Date().toISOString()
  }
}];
